<script setup lang="ts">
import SubscriptionAlertPolicyEditor from "../components/notifications/SubscriptionAlertPolicyEditor.vue";
import ResellerDefaultsEditor from "../components/ResellerDefaultsEditor.vue";
import QrPolicyEditor from "../components/QrPolicyEditor.vue";
import TrialPolicyEditor from "../components/trials/TrialPolicyEditor.vue";
import { computed, onMounted, ref } from "vue";
import { item, request, query, type PreferencesSnapshot, type PreferencesRevision, type Page, type FulfillmentPolicy, type QuotaPolicy } from "@papilio/api";
import { useAuth } from "@papilio/auth";
import { asciiDigits, faDate, faNumber, toman } from "@papilio/ui";
import { kinds as notificationKinds } from "../components/notifications/labels";
import NotificationPolicyEditor from "../components/notifications/NotificationPolicyEditor.vue";
import SupportPolicyEditor from "../components/support/SupportPolicyEditor.vue";
import QuotaPolicyEditor from "../components/QuotaPolicyEditor.vue";
import FulfillmentPolicyEditor from "../components/FulfillmentPolicyEditor.vue";
import NumField from "@papilio/ui/NumField.vue";
import { useBranding } from "../stores/branding";
import PurchaseCheckoutPolicyEditor from "../components/PurchaseCheckoutPolicyEditor.vue";
import CheckoutPolicyEditor from "../components/CheckoutPolicyEditor.vue";
const auth = useAuth(); const branding = useBranding();
const snapshot = ref<PreferencesSnapshot | null>(null); const error = ref(""); const notice = ref(""); const busy = ref(false); const state = ref<"loading" | "ready" | "error">("loading");
const allowRotation = ref(false); const brand = ref(""); const instructions = ref(""); const support = ref(""); const amounts = ref(""); const mode = ref<"reject_new" | "replace_oldest">("reject_new"); const maxIps = ref(""); const lease = ref(""); const ban = ref("");
const fields = [{ key: "max_plan_duration_days", label: "Maximum plan duration (days)" }, { key: "payment_stale_hours", label: "Payment waiting period (hours)" }, { key: "node_health_stale_seconds", label: "Node sample stale after (seconds)" }, { key: "subscription_expiry_warning_hours", label: "Expiry warning (hours)" }, { key: "provisioning_attention_minutes", label: "Provisioning warning delay (minutes)" }] as const;
type NumericKey = typeof fields[number]["key"];
const numbers = ref<Record<NumericKey, string>>({ max_plan_duration_days: "", payment_stale_hours: "", node_health_stale_seconds: "", subscription_expiry_warning_hours: "", provisioning_attention_minutes: "" });
const receipts = ref<import("@papilio/api").ReceiptPolicy|null>(null); const receiptCount=ref("");
const resellerDefaults=ref<import("@papilio/api").ResellerDefaults|null>(null);
const qrPolicy=ref<import("@papilio/api").QrPolicy|null>(null);
const trialPolicy=ref<import("@papilio/api").TrialPolicy|null>(null);
const purchaseDraftValid=ref(true);
const identifierDraftValid=ref(true);
const supportedNoticeKinds=computed(()=>snapshot.value?.capabilities?.supported_notification_kinds);
const transientModes=computed(()=>snapshot.value?.capabilities?.checkout_transient_conflict_modes??[]);
const purchaseSupported=ref(false);
const purchasePolicy=ref<import("@papilio/api").PurchaseCheckoutPolicy|null>(null);
const alertsSupported=ref(false);
const alertPolicy=ref<import("@papilio/api").SubscriptionAlertPolicy>({enabled:false,low_quota:[],expiry_hours:[],renewal_opportunity:false});
const notificationPolicy=ref<import("@papilio/api").NotificationPolicy|null>(null);
const supportPolicy=ref<import("@papilio/api").SupportPolicy|null>(null);
const creationAccess = ref<import("@papilio/api").CustomerAccessState|null>(null);
const checkout = ref<import("@papilio/api").CheckoutPolicy | null>(null);
const quotaPolicy = ref<QuotaPolicy | null>(null); const fulfillment = ref<FulfillmentPolicy | null>(null); const defaultIpEnabled = ref(false);
const history = ref<PreferencesRevision[]>([]); const historyState = ref<"loading" | "ready" | "error">("loading"); const page = ref(1); const pages = ref(1);
async function load(): Promise<void> {
  state.value = "loading"; error.value = "";
  try {
    const result = await item<PreferencesSnapshot>("/v1/admin/settings"); snapshot.value = result; purchaseSupported.value=Object.prototype.hasOwnProperty.call(result.values,"purchase_checkout");purchasePolicy.value=structuredClone(result.values.purchase_checkout??null); alertsSupported.value=Object.prototype.hasOwnProperty.call(result.values,"subscription_alerts"); alertPolicy.value=structuredClone(result.values.subscription_alerts??{enabled:false,low_quota:[],expiry_hours:[],renewal_opportunity:false}); resellerDefaults.value=structuredClone(result.values.reseller_defaults??null); qrPolicy.value=structuredClone(result.values.qr_codes??null); trialPolicy.value=structuredClone(result.values.trials??null); notificationPolicy.value=structuredClone(result.values.notifications??null); supportPolicy.value=structuredClone(result.values.support??null); const values = result.values;
    creationAccess.value = {...values.customer_creation_access}; allowRotation.value = values.customer_link_rotation; brand.value = values.brand_title; instructions.value = values.payment_instructions ?? ""; support.value = values.support_handle ?? ""; amounts.value = values.topup_options_rial.map(value => String(value / 10)).join("\n");
    receipts.value=structuredClone(values.receipts);receiptCount.value=String(values.receipts.max_per_topup); checkout.value = structuredClone(values.checkout); quotaPolicy.value = { ...values.quota_policy }; fulfillment.value = { ...values.fulfillment }; defaultIpEnabled.value = values.ip_defaults.enabled; mode.value = values.ip_defaults.mode; maxIps.value = String(values.ip_defaults.max_ips); lease.value = String(values.ip_defaults.lease_seconds); ban.value = String(values.ip_defaults.ban_seconds);
    for (const field of fields) numbers.value[field.key] = String(values[field.key]); state.value = "ready";
  } catch (cause) { state.value = "error"; error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; }
}
async function loadHistory(): Promise<void> {
  historyState.value = "loading"; const requested = page.value;
  try { const result = await request<Page<PreferencesRevision>>(`/v1/admin/settings/history?${query({ page: requested })}`); if (page.value !== requested) return; history.value = result.data; pages.value = result.meta.pager?.total_pages ?? 1; historyState.value = "ready"; }
  catch (cause) { historyState.value = "error"; error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; }
}
async function save(): Promise<void> {
  if (!snapshot.value) return; if(!identifierDraftValid.value){error.value="Review the payment identifier adjustment and step before saving settings.";return;} if(purchaseSupported.value&&!purchaseDraftValid.value){error.value="Enter a positive checkout lifetime before saving settings.";return;} busy.value = true; error.value = ""; notice.value = "";
  try {
    const options = asciiDigits(amounts.value).replace(/٫/g, ".").split(/[\s,،]+/).filter(Boolean);
    if (!options.length || options.some(value => !/^\d+(?:\.\d)?$/.test(value))) throw new Error("Enter amounts in toman with at most one decimal place.");
    const values = { ...(purchaseSupported.value?{purchase_checkout:purchasePolicy.value}:{}), ...(alertsSupported.value?{subscription_alerts:alertPolicy.value}:{}), reseller_defaults:resellerDefaults.value, qr_codes:qrPolicy.value, trials:trialPolicy.value, notifications: notificationPolicy.value, support: supportPolicy.value, customer_creation_access: creationAccess.value, receipts: receipts.value ? {...receipts.value,max_per_topup:Number(receiptCount.value)} : null, checkout: checkout.value, quota_policy: quotaPolicy.value, customer_link_rotation: allowRotation.value, brand_title: brand.value, payment_instructions: instructions.value.trim() || null, support_handle: support.value.trim() || null, topup_options_rial: options.map(value => Math.round(Number(value) * 10)), max_plan_duration_days: Number(numbers.value.max_plan_duration_days), payment_stale_hours: Number(numbers.value.payment_stale_hours), node_health_stale_seconds: Number(numbers.value.node_health_stale_seconds), subscription_expiry_warning_hours: Number(numbers.value.subscription_expiry_warning_hours), provisioning_attention_minutes: Number(numbers.value.provisioning_attention_minutes), fulfillment: fulfillment.value, ip_defaults: { enabled: defaultIpEnabled.value, mode: mode.value, max_ips: Number(maxIps.value), lease_seconds: Number(lease.value), ban_seconds: Number(ban.value) } };
    snapshot.value = await item<PreferencesSnapshot>("/v1/admin/settings", "PUT", { expected_revision: snapshot.value.revision, values }); notice.value = "Settings saved. Subsequent requests and checks use the updated values."; await branding.refresh(); page.value = 1; await loadHistory();
  } catch (cause) { error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } finally { busy.value = false; }
}
onMounted(async () => { await load(); await loadHistory(); });
</script>
<template>
  <div class="page-head"><div><p class="eyebrow">Business settings</p><h1>Settings</h1><p class="subtitle">Changes are versioned and record the responsible operator.</p></div><button class="btn secondary" :disabled="busy" @click="load">Reload current version</button></div>
  <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message" role="status">{{ notice }}</p><p v-if="state === 'loading'">Loading settings…</p>
  <form v-if="snapshot" class="card card-pad form-grid" @submit.prevent="save"><h2>Revision {{ faNumber(snapshot.revision) }}</h2><fieldset :disabled="!auth.can('settings', 'update') || busy" class="form-grid"><label class="field"><span>Brand name</span><input v-model="brand" required minlength="2" maxlength="100" /></label><label class="field"><span>Payment instructions</span><textarea v-model="instructions" rows="5" maxlength="4000" /></label><label class="field"><span>Telegram support handle</span><input v-model="support" dir="ltr" /></label><label class="field"><span>Suggested top-ups (toman, one amount per line)</span><textarea v-model="amounts" rows="4" /></label><NumField v-for="field in fields" :key="field.key" v-model="numbers[field.key]" :label="field.label" /><label class="check-row"><input v-model="allowRotation" type="checkbox" />Allow customers to rotate their private link through the bot</label><h3>New customer access defaults</h3><template v-if="creationAccess"><label class="check-row"><input v-model="creationAccess.is_active" type="checkbox" />Account sign-in</label><label class="check-row"><input v-model="creationAccess.services_enabled" type="checkbox" />Purchases and service access</label><label class="check-row"><input v-model="creationAccess.renewals_enabled" type="checkbox" />Automatic renewal access</label></template><h3>Private receipt policy</h3><template v-if="receipts"><label class="check-row"><input v-model="receipts.enabled" type="checkbox" />Allow receipt image uploads</label><NumField v-model="receiptCount" label="Maximum receipts per payment" /><label v-for="format in (['JPEG','PNG','WEBP'] as const)" :key="format" class="check-row"><input v-model="receipts.allowed_formats" :value="format" type="checkbox" />{{ format === 'JPEG' ? 'JPEG images' : format === 'PNG' ? 'PNG images' : 'WebP images' }}</label></template><h3>Support policy</h3><h3 v-if="notificationPolicy">Notification policy</h3><QrPolicyEditor v-if="qrPolicy" v-model="qrPolicy" /><TrialPolicyEditor v-if="trialPolicy" v-model="trialPolicy" :disabled="!auth.can('settings','update')" /><SubscriptionAlertPolicyEditor v-if="alertsSupported" v-model="alertPolicy" /><p v-else class="hint-box" role="status">Subscription alert settings are unavailable right now.</p><NotificationPolicyEditor v-if="notificationPolicy" v-model="notificationPolicy" :supported-kinds="supportedNoticeKinds" /><SupportPolicyEditor v-if="supportPolicy" v-model="supportPolicy" /><PurchaseCheckoutPolicyEditor v-if="purchaseSupported" v-model="purchasePolicy" :transient-modes="transientModes" @valid="purchaseDraftValid=$event" /><p v-else class="hint-box">Automated purchase settings are unavailable right now.</p><h3>Wallet top-up policy</h3><CheckoutPolicyEditor v-if="checkout" v-model="checkout" :identifier-capabilities="snapshot.capabilities?.payment_identifiers" @valid="identifierDraftValid=$event" /><ResellerDefaultsEditor v-if="resellerDefaults" v-model="resellerDefaults" :disabled="busy||!auth.can('settings','update')"/><h3>Provisioning and renewal defaults</h3><p>Used for new purchases. Existing purchases retain their saved policies.</p><FulfillmentPolicyEditor v-if="fulfillment" v-model="fulfillment" /><h3>Shared quota defaults</h3><QuotaPolicyEditor v-if="quotaPolicy" v-model="quotaPolicy" /><h3>IP admission defaults</h3><label class="check-row"><input v-model="defaultIpEnabled" type="checkbox" />Apply IP limits to new purchases without a plan-specific policy</label><p>Used for new purchases and policies. Existing subscription policies are unchanged.</p><NumField v-model="maxIps" label="Active IP limit" /><NumField v-model="lease" label="IP lease duration (seconds)" /><NumField v-model="ban" label="Ban duration (seconds)" /><label class="field"><span>Extra IP behavior</span><select v-model="mode"><option value="reject_new">Reject new IP</option><option value="replace_oldest">Replace oldest IP</option></select></label><button v-if="auth.can('settings', 'update')" class="btn" :disabled="busy || state !== 'ready' || !purchaseDraftValid">Save settings</button></fieldset></form>
  <section class="card card-pad" style="margin-top:18px"><h2>Settings history</h2><button class="btn secondary" @click="loadHistory">Refresh History</button><p v-if="historyState === 'loading'">Loading…</p><p v-else-if="historyState === 'error'" class="message error">Could not load history.</p><p v-else-if="!history.length">No revisions saved yet. Current values come from the initial settings.</p><details v-for="row in history" :key="row.revision"><summary>Revision {{ faNumber(row.revision) }} · {{ row.created_at ? faDate(row.created_at) : '—' }} · Operator {{ faNumber(row.changed_by_staff_id) }}</summary><dl><dt>Brand</dt><dd>{{ row.values.brand_title }}</dd><dt>Payment instructions</dt><dd>{{ row.values.payment_instructions ?? '—' }}</dd><dt>Support</dt><dd>{{ row.values.support_handle ?? '—' }}</dd><dt>Top-up amounts</dt><dd>{{ row.values.topup_options_rial.map(toman).join(', ') }}</dd><template v-for="field in fields" :key="field.key"><dt>{{ field.label }}</dt><dd>{{ faNumber(row.values[field.key]) }}</dd></template><template v-if="row.values.quota_policy"><dt>Quota mode</dt><dd>{{ row.values.quota_policy.mode === 'reserved' ? 'Shared reservation' : 'Report Usage' }} · {{ faNumber(row.values.quota_policy.grant_bytes) }} bytes · {{ faNumber(row.values.quota_policy.grant_seconds) }} seconds</dd></template><template v-if="row.values.fulfillment"><dt>Renewal trigger</dt><dd>{{ row.values.fulfillment.renewal_trigger === 'quota' ? 'Quota exhausted' : row.values.fulfillment.renewal_trigger === 'either' ? 'Expiry or quota' : 'Expiry' }}</dd></template><template v-if="row.values.checkout"><dt>Payment destination selection</dt><dd>{{ row.values.checkout.destination_mode === 'required' ? 'Required' : row.values.checkout.destination_mode === 'optional' ? 'Optional' : 'Legacy text instructions' }} · {{ toman(row.values.checkout.minimum_topup_rial) }} to {{ toman(row.values.checkout.maximum_topup_rial) }}</dd></template><template v-if="row.values.checkout?.payment_identifier"><dt>Payment amount identifier</dt><dd>{{row.values.checkout.payment_identifier.mode}} · maximum adjustment {{row.values.checkout.payment_identifier.max_adjustment_rial}} RIAL · step {{row.values.checkout.payment_identifier.amount_step_rial}} RIAL</dd></template><template v-if="row.values.receipts"><dt>Receipt uploads</dt><dd>{{ row.values.receipts.enabled ? 'Enabled' : 'Inactive' }} · {{ faNumber(row.values.receipts.max_per_topup) }} Receipt</dd></template><template v-if="row.values.trials"><dt>Trial policy</dt><dd>{{row.values.trials.enabled?'Active':'Paused'}} · Plan {{row.values.trials.plan_id===null?'Not selected':faNumber(row.values.trials.plan_id)}} · {{row.values.trials.eligibility==='no_paid_purchase'?'No paid purchases':'Any customer'}} · {{row.values.trials.concurrent_mode==='reject_active'?'Reject concurrent subscriptions':'Allow multiple subscriptions'}} · {{faNumber(row.values.trials.max_claims_per_customer)}} Download · {{faNumber(row.values.trials.cooldown_seconds)}} seconds between claims · {{faNumber(row.values.trials.quota_bytes)}} bytes · {{faNumber(row.values.trials.duration_days)}} days</dd></template><template v-if="row.values.purchase_checkout"><dt>Automated purchase policy</dt><dd>{{row.values.purchase_checkout.enabled?"Enabled":"Disabled"}} · {{row.values.purchase_checkout.admission_mode==="require_ready_bundle"?"Available bundle required":"Manual configuration allowed"}} · {{faNumber(row.values.purchase_checkout.default_expiry_seconds)}} seconds</dd></template><dt>Subscription alert rules</dt><dd>{{row.values.subscription_alerts?.enabled?"Enabled":"Disabled"}} · {{row.values.subscription_alerts?.low_quota.length??0}} quota rules · {{row.values.subscription_alerts?.expiry_hours.join(", ")||"No expiry rules"}}</dd><template v-if="row.values.notifications"><dt>Notification policy</dt><dd>{{row.values.notifications.enabled?'Active':'Paused'}} · {{row.values.notifications.channel_mode==='inbox'?'Inbox':row.values.notifications.channel_mode==='telegram'?'Telegram':'Inbox and Telegram'}} · {{row.values.notifications.delivery_enabled?'Delivery enabled':'Delivery paused'}} · {{row.values.notifications.ambiguous_mode==='hold'?'Hold uncertain results for review':'Retry uncertain results'}} · {{row.values.notifications.backoff_mode==='fixed'?'Fixed delay':'Exponential delay'}} · {{faNumber(row.values.notifications.retry_seconds)}} to {{faNumber(row.values.notifications.max_retry_seconds)}} seconds · {{faNumber(row.values.notifications.max_attempts)}} attempts · {{faNumber(row.values.notifications.lease_seconds)}} seconds reserved · {{faNumber(row.values.notifications.max_message_chars)}} characters</dd><template v-for="(template,key) in row.values.notifications.templates" :key="key"><dt>Template {{notificationKinds[key]}}</dt><dd v-if="template">{{template.enabled?'Active':'Paused'}} · {{template.title}} · {{template.body}}</dd><dd v-else>Not configured</dd></template></template><template v-if="row.values.support"><dt>Ticket policy</dt><dd>{{row.values.support.new_tickets_enabled?'New tickets enabled':'New tickets paused'}} · {{row.values.support.customer_replies_enabled?'Customer replies enabled':'Customer replies paused'}} · {{row.values.support.staff_replies_enabled?'Staff replies enabled':'Staff replies paused'}} · {{faNumber(row.values.support.max_open_tickets)}} open tickets · {{faNumber(row.values.support.max_messages_per_ticket)}} Message · {{faNumber(row.values.support.max_message_chars)}} characters · {{row.values.support.closed_reply_mode==='reject'?'Reject replies to closed tickets':'Accept replies to closed tickets'}} · {{row.values.support.customer_closure_enabled?'Customer closure enabled':'Customer closure paused'}} · {{row.values.support.customer_reopen_enabled?'Customer reopening enabled':'Customer reopening paused'}} · {{row.values.support.staff_reply_status==='open'?'Waiting for support':row.values.support.staff_reply_status==='closed'?'Closed':'Waiting for customer'}}</dd></template><template v-if="row.values.qr_codes"><dt>Connection QR code</dt><dd>{{row.values.qr_codes.enabled?'Active':'Paused'}} · {{faNumber(row.values.qr_codes.box_size)}} pixels · {{faNumber(row.values.qr_codes.border_modules)}} border modules · {{({L:'Low',M:'Medium',Q:'High',H:'Maximum'})[row.values.qr_codes.error_correction]}}</dd></template><template v-if="row.values.reseller_defaults"><dt>Reseller defaults</dt><dd><ResellerDefaultsEditor :model-value="row.values.reseller_defaults" disabled/></dd></template><dt>IP policy</dt><dd>{{ faNumber(row.values.ip_defaults.max_ips) }} · Validity {{ faNumber(row.values.ip_defaults.lease_seconds) }} seconds · Ban {{ faNumber(row.values.ip_defaults.ban_seconds) }} seconds · {{ row.values.ip_defaults.mode === 'reject_new' ? 'Reject new IP' : 'Replace oldest' }}</dd></dl></details><div class="pager"><button :disabled="page <= 1" @click="page--; loadHistory()">‹</button><span>{{ faNumber(page) }}</span><button :disabled="page >= pages" @click="page++; loadHistory()">›</button></div></section>
</template>

<style scoped>
fieldset { border: 0; margin: 0; padding: 0; min-inline-size: 0; }
dd { margin-inline-start: 0; overflow-wrap: anywhere; }
</style>
